import ctypes, ctypes.wintypes as wt, os

k32 = ctypes.WinDLL("kernel32", use_last_error=True)
QDD = k32.QueryDosDeviceW
QDD.argtypes = [wt.LPCWSTR, wt.LPWSTR, wt.DWORD]
QDD.restype = wt.DWORD

def build_device_map():
    """Build a mapping from NT device paths to DOS drive letters."""
    mapping = {}
    dbuf = ctypes.create_unicode_buffer(260)
    for c in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
        drive = c + ":"
        n = QDD(drive, dbuf, 260)
        if n:
            nt_path = dbuf.value
            # nt_path is like \Device\HarddiskVolume4
            mapping[nt_path.lower()] = drive
    return mapping

def nt_to_dos(nt_path, device_map):
    """Convert an NT path to a DOS path using the device map."""
    if not nt_path:
        return None

    nt_lower = nt_path.lower()

    # Try to find a matching device prefix
    best_match = None
    best_len = 0
    for dev_name, drive_letter in device_map.items():
        if nt_lower.startswith(dev_name + "\\") or nt_lower == dev_name:
            if len(dev_name) > best_len:
                best_len = len(dev_name)
                best_match = (dev_name, drive_letter)

    if best_match:
        dev_name, drive_letter = best_match
        remainder = nt_path[len(dev_name):]
        if remainder.startswith("\\"):
            return drive_letter + remainder
        elif not remainder:
            return drive_letter + "\\"

    # Handle \\?\ prefix paths
    if nt_path.startswith("\\??\\"):
        return nt_path[3:]  # Remove leading backslash to get \X:\... -> X:\...

    return None

device_map = build_device_map()
print("Device map:", device_map)

# Test with known paths
test_paths = [
    r"\Device\HarddiskVolume4\Windows\System32\kernel32.dll",
    r"\Device\vmsmb\VSMB-{dcc079ae-60ba-4d07-847c-3493609c0870}\EF1C7BAF-9DC4-5D2D-AD94-D515E6FA7579\Files\Python312\python.exe",
]

for p in test_paths:
    result = nt_to_dos(p, device_map)
    print(f"{p} -> {result}")
    if result:
        print(f"  exists: {os.path.exists(result)}")
